<?php

declare(strict_types=1);

use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Http\UploadedFile;
use Inertia\Testing\AssertableInertia;
use Modules\SampleAdmin\Models\SampleAdmin;
use Yuan\AdminCore\Audit\ImmutableActivity;
use Yuan\AdminCore\Testing\ModuleAssertions;

use function Pest\Laravel\delete;
use function Pest\Laravel\get;
use function Pest\Laravel\post;
use function Pest\Laravel\put;

// Contoh khusus Super Admin (generated by make:module): the AGENTS §8 cases for each declared action.

uses(RefreshDatabase::class);

/**
 * A valid form submission, as the create page sends it.
 *
 * @param  array<string, mixed>  $overrides
 * @return array<string, mixed>
 */
function sampleAdminInput(array $overrides = []): array
{
    return [
        'judul' => 'Contoh Judul',
        'catatan' => 'Catatan contoh',
        'files' => ['berkas' => [UploadedFile::fake()->create('berkas.pdf', 10)]],
        ...$overrides,
    ];
}

it('redirects guests to login', function (): void {
    $sampleAdmin = SampleAdmin::factory()->create();

    ModuleAssertions::assertGuestRedirected('get', '/admin/sample-admin');
    ModuleAssertions::assertGuestRedirected('get', "/admin/sample-admin/{$sampleAdmin->id}");
    ModuleAssertions::assertGuestRedirected('get', '/admin/sample-admin/create');
    ModuleAssertions::assertGuestRedirected('post', '/admin/sample-admin');
    ModuleAssertions::assertGuestRedirected('get', "/admin/sample-admin/{$sampleAdmin->id}/edit");
    ModuleAssertions::assertGuestRedirected('put', "/admin/sample-admin/{$sampleAdmin->id}");
    ModuleAssertions::assertGuestRedirected('delete', "/admin/sample-admin/{$sampleAdmin->id}");
    ModuleAssertions::assertGuestRedirected('delete', '/admin/sample-admin');
});

it('refuses every other level, even one holding every permission there is', function (): void {
    $sampleAdmin = SampleAdmin::factory()->create();
    ModuleAssertions::actingAsLevelWith(['users.view', 'users.create', 'users.edit', 'users.delete', 'users.download']);

    get('/admin/sample-admin')->assertForbidden();
    get("/admin/sample-admin/{$sampleAdmin->id}")->assertForbidden();
});

it('lists and shows contoh khusus super admin records', function (): void {
    $sampleAdmin = SampleAdmin::factory()->create();
    ModuleAssertions::actingAsSuperAdmin();

    AssertableInertia::fromTestResponse(get('/admin/sample-admin')->assertOk())
        ->component('SampleAdmin::Index')
        ->count('sampleAdmins.items', 1)
        ->where('sampleAdmins.items.0.id', $sampleAdmin->id);

    AssertableInertia::fromTestResponse(get("/admin/sample-admin/{$sampleAdmin->id}")->assertOk())
        ->component('SampleAdmin::Show')
        ->where('sampleAdmin.id', $sampleAdmin->id)
        ->where('breadcrumbs.items.1.label', $sampleAdmin->auditLabel());
});

it('rejects a sort the list does not allow', function (): void {
    ModuleAssertions::actingAsSuperAdmin();

    get('/admin/sample-admin?sort=lock_version')->assertStatus(400);
});

it('scopes every contoh khusus super admin query to the signed-in user', function (): void {
    $sampleAdmin = SampleAdmin::factory()->create();
    ModuleAssertions::actingAsSuperAdmin();

    ModuleAssertions::assertScopedToUser(SampleAdmin::class, 'get', '/admin/sample-admin');
    ModuleAssertions::assertScopedToUser(SampleAdmin::class, 'get', "/admin/sample-admin/{$sampleAdmin->id}");
    ModuleAssertions::assertScopedToUser(SampleAdmin::class, 'get', "/admin/sample-admin/{$sampleAdmin->id}/edit");
    ModuleAssertions::assertScopedToUser(SampleAdmin::class, 'put', "/admin/sample-admin/{$sampleAdmin->id}", sampleAdminInput(['lock_version' => $sampleAdmin->lock_version]));
    ModuleAssertions::assertScopedToUser(SampleAdmin::class, 'delete', '/admin/sample-admin', ['ids' => [$sampleAdmin->id]]);
    ModuleAssertions::assertScopedToUser(SampleAdmin::class, 'delete', "/admin/sample-admin/{$sampleAdmin->id}");
});

it('creates a contoh khusus super admin and audits it', function (): void {
    ModuleAssertions::actingAsSuperAdmin();

    post('/admin/sample-admin', sampleAdminInput())->assertSessionHasNoErrors()->assertRedirect();

    $sampleAdmin = SampleAdmin::query()->sole();
    ModuleAssertions::assertAudited($sampleAdmin, 'created');
});

it('rejects a contoh khusus super admin without its required fields', function (): void {
    ModuleAssertions::actingAsSuperAdmin();

    post('/admin/sample-admin', [])->assertSessionHasErrors(['judul']);

    expect(SampleAdmin::query()->count())->toBe(0);
});

it('updates a contoh khusus super admin and audits the change', function (): void {
    $sampleAdmin = SampleAdmin::factory()->create();
    ModuleAssertions::actingAsSuperAdmin();

    AssertableInertia::fromTestResponse(get("/admin/sample-admin/{$sampleAdmin->id}/edit")->assertOk())
        ->component('SampleAdmin::Edit')
        ->where('sampleAdmin.lock_version', 0);

    put("/admin/sample-admin/{$sampleAdmin->id}", sampleAdminInput(['lock_version' => $sampleAdmin->lock_version]))
        ->assertSessionHasNoErrors()
        ->assertRedirect("/admin/sample-admin/{$sampleAdmin->id}");

    ModuleAssertions::assertAudited($sampleAdmin, 'updated');
});

it('gives the second of two saves from the same form a 409 and keeps the first', function (): void {
    $sampleAdmin = SampleAdmin::factory()->create();
    ModuleAssertions::actingAsSuperAdmin();

    put("/admin/sample-admin/{$sampleAdmin->id}", sampleAdminInput(['lock_version' => 0]))->assertRedirect();
    put("/admin/sample-admin/{$sampleAdmin->id}", sampleAdminInput(['lock_version' => 0]))->assertStatus(409);

    expect($sampleAdmin->fresh()?->lock_version)->toBe(1);
});

it('moves a contoh khusus super admin to the trash and audits it', function (): void {
    $sampleAdmin = SampleAdmin::factory()->create();
    ModuleAssertions::actingAsSuperAdmin();

    delete("/admin/sample-admin/{$sampleAdmin->id}")->assertRedirect();

    expect($sampleAdmin->fresh()?->trashed())->toBeTrue();
    ModuleAssertions::assertAudited($sampleAdmin, 'deleted');
});

it('deletes the selected records in one audit batch', function (): void {
    [$first, $second] = SampleAdmin::factory()->count(2)->create()->all();
    ModuleAssertions::actingAsSuperAdmin();

    delete('/admin/sample-admin', ['ids' => [$first->id, $second->id]])->assertRedirect();

    expect(SampleAdmin::query()->count())->toBe(0)
        ->and(ImmutableActivity::query()->where('event', 'deleted')->pluck('batch_uuid')->unique()->filter())->toHaveCount(1);
});
